        dtype=ArrowDtype(pa.duration("ns")),
    )
    arr = ser.array
    arr._dt_day_remainder  # populate the cache
    assert "_dt_day_remainder" in arr._cache

    result = tm.round_trip_pickle(arr, tmp_path / "cache.pkl")
