    if isinstance(expected, pd.Timestamp):
        expected = expected.date()
    assert result[0] == expected

    result = ser - offset
    expected = date(2022, 12, 30) - offset
    if isinstance(expected, pd.Timestamp):
        expected = expected.date()
    assert result[0] == expected

