def make_data(n: int):
    while True:
        values = np.random.default_rng(2).choice(list(string.ascii_letters), size=n)
        # ensure we meet the requirements
        # 1. first two not null
        # 2. first and second are different
        if values[0] != values[1]:
            break
    return values


